candidate.runner_source:
param([Parameter(Mandatory=$true)][string]$TestExecutable)
$ErrorActionPreference = 'Stop'
$taskRepo = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
Set-Location -LiteralPath $taskRepo
function Digest($taskPath) { (Get-FileHash -LiteralPath $taskPath).Hash.ToLowerInvariant() }
function Save-Json($taskPath, $taskValue) { [IO.File]::WriteAllText($taskPath, ($taskValue | ConvertTo-Json -Depth 100) + "`n") }
function Sources {
    @(git ls-files -c -o --exclude-standard src examples tools Cargo.toml Cargo.lock rust-toolchain.toml | Sort-Object -Unique | ForEach-Object {
        [ordered]@{path=$_;sha256=Digest (Join-Path $taskRepo $_)}
    })
}
$taskSources = Sources
$taskSourceText = $taskSources | ConvertTo-Json -Compress
$taskExe = Join-Path $PSScriptRoot 'pad-v1-owner.exe'
$TestExecutable = (Resolve-Path -LiteralPath $TestExecutable).Path
$taskHashes = @($taskExe,$TestExecutable) | ForEach-Object { [ordered]@{path=$_;sha256=Digest $_} }
$taskGraph = Get-Content (Join-Path $PSScriptRoot 'pad-v1-graphs.json') -Raw | ConvertFrom-Json
$taskSpent = $taskGraph.execution_seconds
$taskRuns = @()
$taskCases = @(@('tiny','imgs_1'),@('tiny','imgs_00018069'),@('tiny','imgs_00006737'),@('small','imgs_00018069'),@('medium','imgs_00018069'))
foreach ($taskCase in $taskCases) {
    $taskStem = Join-Path $PSScriptRoot ('pad-v1-page-' + $taskCase[0] + '-' + $taskCase[1])
    if (Test-Path ($taskStem + '.json')) { throw 'Refuse to overwrite measurements' }
    $taskArgs = @($taskCase[0],$taskCase[1],'0','1')
    $taskTimeout = [int][Math]::Min(10000, (60 - $taskSpent) * 1000)
    if ($taskTimeout -lt 1000) { throw 'Performance execution budget exhausted' }
    $taskTimer = [Diagnostics.Stopwatch]::StartNew()
    $taskProc = Start-Process -FilePath $taskExe -ArgumentList $taskArgs -WindowStyle Hidden -RedirectStandardOutput ($taskStem + '.json') -RedirectStandardError ($taskStem + '.log') -PassThru
    if (-not $taskProc.WaitForExit($taskTimeout)) { Stop-Process -Id $taskProc.Id -Force; throw 'Page probe timeout' }
    $taskProc.WaitForExit()
    $taskTimer.Stop()
    $taskSpent += $taskTimer.Elapsed.TotalSeconds
    if ($taskProc.ExitCode -ne 0) { throw 'Page probe failed' }
    $taskNew = Get-Content ($taskStem + '.json') -Raw | ConvertFrom-Json
    $taskOldPath = Join-Path $PSScriptRoot ('../pipeline-analysis-20261018/ordinary-' + $taskCase[0] + '-' + $taskCase[1] + '.json')
    $taskOld = Get-Content $taskOldPath -Raw | ConvertFrom-Json
    foreach ($taskProperty in @('control_output_sha256','pixel_sha256','manifest_sha256','recognized_lines','affinity','cpu_context_capacity')) {
        if ($taskOld.$taskProperty -ne $taskNew.$taskProperty) { throw "Page parity failure: $taskProperty" }
    }
    if (-not $taskNew.complete_owned_outputs_exactly_equal) { throw 'Missing measured output parity' }
    $taskRuns += [ordered]@{case=$taskCase;arguments=$taskArgs;wall_seconds=$taskTimer.Elapsed.TotalSeconds;baseline=$taskOld;candidate=$taskNew}
    $taskMedian = @($taskNew.cases[0].samples_ms | Sort-Object)[1]
    Write-Output "$($taskCase -join ' '): $taskMedian ms; complete output digest preserved"
}
$taskStem = Join-Path $PSScriptRoot 'pad-v1-detector-operators'
if (Test-Path ($taskStem + '.txt')) { throw 'Refuse to overwrite operator measurements' }
$taskArgs = @('runtime::optimized::tests::performance::sparse_detector_production_steps','--exact','--ignored','--nocapture','--test-threads=1')
$taskTimeout = [int][Math]::Min(15000, (60 - $taskSpent) * 1000)
if ($taskTimeout -lt 1000) { throw 'Performance execution budget exhausted' }
$taskTimer = [Diagnostics.Stopwatch]::StartNew()
$taskProc = Start-Process -FilePath $TestExecutable -ArgumentList $taskArgs -WindowStyle Hidden -RedirectStandardOutput ($taskStem + '.txt') -RedirectStandardError ($taskStem + '.log') -PassThru
if (-not $taskProc.WaitForExit($taskTimeout)) { Stop-Process -Id $taskProc.Id -Force; throw 'Operator probe timeout' }
$taskProc.WaitForExit()
$taskTimer.Stop()
$taskSpent += $taskTimer.Elapsed.TotalSeconds
$taskOperators = Get-Content ($taskStem + '.txt') -Raw
if ($taskProc.ExitCode -ne 0 -or $taskOperators -notmatch 'test result: ok\. 1 passed') { throw 'Operator probe failed' }
if ($taskSourceText -ne ((Sources) | ConvertTo-Json -Compress)) { throw 'Sources changed while measuring' }
foreach ($taskHash in $taskHashes) { if ($taskHash.sha256 -ne (Digest $taskHash.path)) { throw 'Executable changed while measuring' } }
Save-Json (Join-Path $PSScriptRoot 'pad-v1-evidence.json') ([ordered]@{
    schema_version=1; timestamp=(Get-Date).ToString('o');git_head=(git rev-parse HEAD).Trim();sources=$taskSources;executables=$taskHashes
    source_and_executables_stable=$true;graph_execution=$taskGraph;pages=$taskRuns
    operators=[ordered]@{arguments=$taskArgs;wall_seconds=$taskTimer.Elapsed.TotalSeconds;output=$taskOperators}
    total_performance_execution_seconds=$taskSpent;budget_seconds=60
    baseline_reuse='Page baseline is the earlier same-day, same-revision, same-host measurement with identical frozen harness and inputs; it was not rerun. Non-interleaved page samples cannot isolate small changes from host variation.'
    page_scope='Three real input pages; Tiny sparse/dense/mixed plus Small/Medium dense controls. One warm-up and three measured runs per case. CPU24 affinity ffffff, automatic owners, recognition batch one.'
    graph_scope='Two representative PadEnd2 spatial shapes; one warm-up and three measurements per source version at CPU8 affinity ff.'
    operator_scope='Three real-input sparse detector models; one warm-up and one measured instrumented graph per version at CPU8 affinity ff. Do not combine with ordinary samples.'
    cpu=@(Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors)
    power_scheme=(powercfg /getactivescheme | Out-String);rustc=(rustc -Vv | Out-String)
    runner_source=[IO.File]::ReadAllText($PSCommandPath)
})
Write-Output "Total candidate performance execution: $taskSpent s"

synthetic_model_generator:
from pathlib import Path
import struct

def var(n):
    out=bytearray()
    while n>=128:
        out.append((n&127)|128)
        n>>=7
    out.append(n)
    return bytes(out)
def num(f,n): return var(f*8)+var(n)
def blob(f,b): return var(f*8+2)+var(len(b))+b
def info(name,channels):
    dims=b''.join(blob(1,num(1,n) if n else blob(2,f'dim{i}'.encode())) for i,n in enumerate([1,channels,0,0]))
    return blob(1,name.encode())+blob(2,blob(1,num(1,1)+blob(2,dims)))
def tensor(name,dims,values):
    return blob(5,b''.join(num(1,n) for n in dims)+num(2,1)+blob(8,name.encode())+blob(9,struct.pack('<'+'f'*len(values),*values)))
def attr(name,values): return blob(5,blob(1,name.encode())+num(20,7)+b''.join(num(8,n) for n in values))
graph=tensor('w',[8,16,2,2],[((i*13%79)-39)/64 for i in range(512)])
graph+=tensor('b',[8],[(i-3)/32 for i in range(8)])
graph+=blob(1,b''.join(blob(1,n.encode()) for n in ['x','w','b'])+blob(2,b'y')+blob(4,b'Conv')+attr('kernel_shape',[2,2])+attr('pads',[0,0,1,1]))
graph+=blob(11,info('x',16))+blob(12,info('y',8))
path=Path(__file__).with_name('pad-end-16-8.onnx')
if path.exists(): raise RuntimeError('Refuse to overwrite model')
path.write_bytes(num(1,8)+blob(8,num(2,13))+blob(7,graph))
print(path)

graph_runner:
param([Parameter(Mandatory=$true)][string]$Variant,[Parameter(Mandatory=$true)][string]$Executable)
$ErrorActionPreference = 'Stop'
$Executable = (Resolve-Path -LiteralPath $Executable).Path
$taskRows = @()
$taskSeconds = 0.0
foreach ($taskCase in @(@('large','1,16,480,304'),@('dense','1,16,128,208'))) {
    $taskStem = Join-Path $PSScriptRoot ($Variant + '-pad-' + $taskCase[0])
    if (Test-Path ($taskStem + '.json')) { throw 'Refuse to overwrite measurements' }
    $taskArgs = @('--model',(Join-Path $PSScriptRoot 'pad-end-16-8.onnx'),'--shape',$taskCase[1],'--threads','8','--budget-seconds','10','--label',$Variant)
    $taskTimer = [Diagnostics.Stopwatch]::StartNew()
    $taskProc = Start-Process -FilePath $Executable -ArgumentList $taskArgs -WindowStyle Hidden -RedirectStandardOutput ($taskStem + '.json') -RedirectStandardError ($taskStem + '.log') -PassThru
    if (-not $taskProc.WaitForExit(10000)) { Stop-Process -Id $taskProc.Id -Force; throw 'Graph probe timeout' }
    $taskProc.WaitForExit()
    $taskSeconds += $taskTimer.Elapsed.TotalSeconds
    if ($taskProc.ExitCode -ne 0) { Get-Content ($taskStem + '.log'); throw 'Graph probe failed' }
    $taskResult = Get-Content ($taskStem + '.json') -Raw | ConvertFrom-Json
    $taskRows += [ordered]@{case=$taskCase[0];arguments=$taskArgs;wall_seconds=$taskTimer.Elapsed.TotalSeconds;result=$taskResult}
    Write-Output "$Variant $($taskCase[0]): $($taskResult.cases[0].median_ms) ms"
}
[ordered]@{variant=$Variant;execution_seconds=$taskSeconds;executable_sha256=(Get-FileHash $Executable).Hash;execution=$taskRows} | ConvertTo-Json -Depth 60 | Set-Content (Join-Path $PSScriptRoot ($Variant + '-graphs.json'))

